package app

import (
	"sync"

	"fyne.io/fyne/v2"
)

var (
	metaMutex sync.RWMutex
	meta      = fyne.AppMetadata{
		ID:      "com.example",
		Name:    "Fyne App",
		Version: "1.0.0",
		Build:   1,
	}
)

// SetMetadata sets the application metadata that will be returned by all App instances.
// This allows you to override the default metadata at runtime.
//
// Since: 2.2
func SetMetadata(m fyne.AppMetadata) {
	metaMutex.Lock()
	defer metaMutex.Unlock()
	meta = m
}

func currentMetadata() fyne.AppMetadata {
	metaMutex.RLock()
	defer metaMutex.RUnlock()
	return meta
}

