// Refresh causes this menu to update and redraw in all windows where it is currently displayed.
// This allows runtime changes to menu items (including icons and shortcuts) to be reflected.
//
// Since: 2.2
func (m *Menu) Refresh() {
	app := CurrentApp()
	if app == nil {
		return
	}

	// Refresh all windows that might be using this menu
	for _, window := range app.Driver().AllWindows() {
		if window.MainMenu() != nil {
			for _, menu := range window.MainMenu().Items {
				if menu == m {
					window.SetMainMenu(window.MainMenu())
					break
				}
			}
		}
	}

	// Also refresh system tray if this is the tray menu
	if desk, ok := app.(interface{ SystemTrayMenu() *Menu }); ok {
		if desk.SystemTrayMenu() == m {
			if setter, ok := app.(interface{ SetSystemTrayMenu(*Menu) }); ok {
				setter.SetSystemTrayMenu(m)
			}
		}
	}
}

