// MinSize returns the size that this widget should not shrink below.
//
// Implements: fyne.Widget
func (e *Entry) MinSize() fyne.Size {
	e.ExtendBaseWidget(e)

	min := e.BaseWidget.MinSize()
	if e.ActionItem != nil {
		min = min.Add(fyne.NewSize(theme.IconInlineSize()+theme.Padding(), 0))
	}
	if e.Validator != nil {
		min = min.Add(fyne.NewSize(theme.IconInlineSize()+theme.Padding(), 0))
	}

	// Respect minimum rows if set
	if e.minRowsVisible > 0 && e.MultiLine {
		textSize := e.text.MinSize()
		lineHeight := textSize.Height
		if len(e.text.Segments) > 0 {
			// Estimate line height from first segment
			lineHeight = theme.TextSize() * theme.LineSpacing()
		}
		minHeight := float32(e.minRowsVisible) * lineHeight
		if min.Height < minHeight {
			min.Height = minHeight
		}
	}

	return min
}

