package validation

import "fyne.io/fyne/v2"

// allStringsValidator is a validator that runs multiple validators in sequence
type allStringsValidator struct {
	validators []fyne.StringValidator
}

// Validate runs all validators in order and returns the first error encountered.
// If all validators pass, it returns nil.
func (v *allStringsValidator) Validate(text string) error {
	for _, validator := range v.validators {
		if validator == nil {
			continue
		}
		if err := validator(text); err != nil {
			return err
		}
	}
	return nil
}

// NewAllStrings returns a StringValidator that runs all provided validators in order
// and returns the first error encountered (or nil if all pass).
//
// Since: 2.2
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	v := &allStringsValidator{validators: validators}
	return v.Validate
}

