package theme

import (
	"encoding/json"
	"io"

	"fyne.io/fyne/v2"
)

// FromJSON creates a custom theme by loading values from JSON data.
// The JSON structure maps theme property names to their values.
// Properties not specified in the JSON will fall back to the default theme.
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader([]byte(data))
}

// FromJSONReader creates a custom theme by loading values from a JSON reader.
// The JSON structure maps theme property names to their values.
// Properties not specified in the JSON will fall back to the default theme.
//
// Since: 2.2
func FromJSONReader(data []byte) (fyne.Theme, error) {
	var themeData map[string]interface{}
	if err := json.Unmarshal(data, &themeData); err != nil {
		return nil, err
	}

	return &jsonTheme{
		data:    themeData,
		variant: VariantDark,
	}, nil
}

// jsonTheme is a theme implementation that loads values from JSON
type jsonTheme struct {
	data    map[string]interface{}
	variant fyne.ThemeVariant
}

func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Try to find the color in JSON data
	key := string(name)
	if variant == VariantLight {
		key = key + "_light"
	} else {
		key = key + "_dark"
	}

	if colorData, ok := t.data[key]; ok {
		if colorStr, ok := colorData.(string); ok {
			if c, err := parseColor(colorStr); err == nil {
				return c
			}
		}
	}

	// Fall back to default theme
	return DefaultTheme().Color(name, variant)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	// Fonts are not customizable via JSON in this implementation
	return DefaultTheme().Font(style)
}

func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	// Icons are not customizable via JSON in this implementation
	return DefaultTheme().Icon(name)
}

func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	// Try to find the size in JSON data
	key := string(name)
	if sizeData, ok := t.data[key]; ok {
		switch v := sizeData.(type) {
		case float64:
			return float32(v)
		case float32:
			return v
		case int:
			return float32(v)
		}
	}

	// Fall back to default theme
	return DefaultTheme().Size(name)
}

// parseColor converts a hex color string (e.g., "#RRGGBB" or "#RRGGBBAA") to a color.Color
func parseColor(s string) (color.Color, error) {
	if len(s) == 0 || s[0] != '#' {
		return nil, io.ErrUnexpectedEOF
	}

	hexToByte := func(b byte) (byte, error) {
		switch {
		case b >= '0' && b <= '9':
			return b - '0', nil
		case b >= 'a' && b <= 'f':
			return b - 'a' + 10, nil
		case b >= 'A' && b <= 'F':
			return b - 'A' + 10, nil
		}
		return 0, io.ErrUnexpectedEOF
	}

	s = s[1:]
	if len(s) != 6 && len(s) != 8 {
		return nil, io.ErrUnexpectedEOF
	}

	var r, g, b, a byte
	var err error

	if r, err = hexToByte(s[0]); err != nil {
		return nil, err
	}
	r = r*16 + func() byte { v, _ := hexToByte(s[1]); return v }()

	if g, err = hexToByte(s[2]); err != nil {
		return nil, err
	}
	g = g*16 + func() byte { v, _ := hexToByte(s[3]); return v }()

	if b, err = hexToByte(s[4]); err != nil {
		return nil, err
	}
	b = b*16 + func() byte { v, _ := hexToByte(s[5]); return v }()

	a = 255
	if len(s) == 8 {
		if a, err = hexToByte(s[6]); err != nil {
			return nil, err
		}
		a = a*16 + func() byte { v, _ := hexToByte(s[7]); return v }()
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

