package binding

import (
	"fmt"

	"fyne.io/fyne/v2/data/binding"
)

// sprintf is a StringBinding that formats multiple source bindings using fmt.Sprintf
type sprintf struct {
	base
	format  string
	sources []binding.DataItem
}

// NewSprintf creates a new string binding that formats its value using the specified format string
// and source data bindings. The format string follows fmt.Sprintf conventions.
// Whenever any source binding changes, the formatted value is recomputed.
//
// Since: 2.2
func NewSprintf(format string, sources ...binding.DataItem) binding.String {
	s := &sprintf{
		format:  format,
		sources: sources,
	}

	// Listen to all source bindings
	for _, source := range sources {
		if source != nil {
			source.AddListener(binding.NewDataListener(func() {
				s.trigger()
			}))
		}
	}

	return s
}

// Get returns the formatted string value using all source bindings
func (s *sprintf) Get() (string, error) {
	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		if source == nil {
			values[i] = nil
			continue
		}

		var val interface{}
		var err error

		switch src := source.(type) {
		case binding.String:
			val, err = src.Get()
		case binding.Int:
			val, err = src.Get()
		case binding.Float:
			val, err = src.Get()
		case binding.Bool:
			val, err = src.Get()
		case binding.Untyped:
			val, err = src.Get()
		default:
			return "", fmt.Errorf("unsupported binding type at index %d", i)
		}

		if err != nil {
			return "", err
		}
		values[i] = val
	}

	return fmt.Sprintf(s.format, values...), nil
}

// Set is not supported for sprintf bindings as they are read-only computed values
func (s *sprintf) Set(string) error {
	return fmt.Errorf("cannot set value on a computed sprintf binding")
}

// StringToStringWithFormat creates a string binding that reformats another string binding.
// This is a convenience wrapper around NewSprintf for the common case of formatting a single string.
//
// Since: 2.2
func StringToStringWithFormat(source binding.String, format string) binding.String {
	return NewSprintf(format, source)
}

// base provides the common listener functionality for bindings
type base struct {
	listeners []binding.DataListener
}

func (b *base) AddListener(listener binding.DataListener) {
	b.listeners = append(b.listeners, listener)
}

func (b *base) RemoveListener(listener binding.DataListener) {
	for i, l := range b.listeners {
		if l == listener {
			b.listeners = append(b.listeners[:i], b.listeners[i+1:]...)
			return
		}
	}
}

func (b *base) trigger() {
	for _, listener := range b.listeners {
		listener.DataChanged()
	}
}

