	// Try generic "Colors" map
	if colorsMap, ok := t.data["Colors"].(map[string]interface{}); ok {
		if colorData, ok := colorsMap[string(name)]; ok {
			if colorStr, ok := colorData.(string); ok {
				if c, err := parseColor(colorStr); err == nil {
					return c
				}
			}
		}
	}

	// Fall back to default theme
	return DefaultTheme().Color(name, variant)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	// Check for "Fonts" map
	if fontsMap, ok := t.data["Fonts"].(map[string]interface{}); ok {
		// Build key from style properties
		var key string
		if style.Bold && style.Italic {
			key = "BoldItalic"
		} else if style.Bold {
			key = "Bold"
		} else if style.Italic {
			key = "Italic"
		} else if style.Monospace {
			key = "Monospace"
		} else {
			key = "Regular"
		}

		if uriStr, ok := fontsMap[key].(string); ok {
			if u, err := parseURI(uriStr); err == nil {
