// sprintf is a StringBinding that formats multiple source bindings using fmt.Sprintf
type sprintf struct {
	base
	format  string
	sources []DataItem
}

// NewSprintf creates a new string binding that formats its value using the specified format string
// and source data bindings. The format string follows fmt.Sprintf conventions.
// Whenever any source binding changes, the formatted value is recomputed.
//
// Since: 2.2
func NewSprintf(format string, sources ...DataItem) String {
	s := &sprintf{
		format:  format,
		sources: sources,
	}

	// Listen to all source bindings
	for _, source := range sources {
		if source != nil {
			source.AddListener(NewDataListener(func() {
				s.trigger()
			}))
		}
	}

	return s
}

// Get returns the formatted string value using all source bindings
func (s *sprintf) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		if source == nil {
			values[i] = nil
			continue
		}

		var val interface{}
		var err error

		switch src := source.(type) {
		case String:
			val, err = src.Get()
		case Int:
			val, err = src.Get()
		case Float:
			val, err = src.Get()
		case Bool:
			val, err = src.Get()
		case Untyped:
			val, err = src.Get()
		default:
			return "", fmt.Errorf("unsupported binding type at index %d", i)
		}

		if err != nil {
			return "", err
		}
		values[i] = val
	}

	return fmt.Sprintf(s.format, values...), nil
}

// Set parses the string back using fmt.Sscanf and sets each source binding to the parsed value.
// URI bindings are parsed via storage.ParseURI. Bytes bindings cannot be round-tripped and return an error.
func (s *sprintf) Set(str string) error {
	s.lock.Lock()
	defer s.lock.Unlock()

	// Prepare pointers for Sscanf to write into
	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		if source == nil {
			return fmt.Errorf("source at index %d is nil", i)
		}

		switch source.(type) {
		case String:
			var v string
			values[i] = &v
		case Int:
			var v int
			values[i] = &v
		case Float:
			var v float64
			values[i] = &v
		case Bool:
			var v bool
			values[i] = &v
		case Bytes:
			return fmt.Errorf("cannot round-trip Bytes binding")
		case URI:
			var v string
			values[i] = &v
		case Untyped:
			var v interface{}
			values[i] = &v
		default:
			return fmt.Errorf("unsupported binding type at index %d", i)
		}
	}

	// Parse using Sscanf
	n, err := fmt.Sscanf(str, s.format, values...)
	if err != nil {
		return fmt.Errorf("failed to parse string: %w", err)
	}
	if n != len(s.sources) {
		return fmt.Errorf("expected %d values, got %d", len(s.sources), n)
	}

	// Set each source binding
	for i, source := range s.sources {
		switch src := source.(type) {
		case String:
			v := *(values[i].(*string))
			if err := src.Set(v); err != nil {
				return fmt.Errorf("failed to set source %d: %w", i, err)
			}
		case Int:
			v := *(values[i].(*int))
			if err := src.Set(v); err != nil {
				return fmt.Errorf("failed to set source %d: %w", i, err)
			}
		case Float:
			v := *(values[i].(*float64))
			if err := src.Set(v); err != nil {
				return fmt.Errorf("failed to set source %d: %w", i, err)
			}
		case Bool:
			v := *(values[i].(*bool))
			if err := src.Set(v); err != nil {
				return fmt.Errorf("failed to set source %d: %w", i, err)
			}
		case URI:
			v := *(values[i].(*string))
			u, err := storage.ParseURI(v)
			if err != nil {
				return fmt.Errorf("failed to parse URI at source %d: %w", i, err)
			}
			if err := src.Set(u); err != nil {
				return fmt.Errorf("failed to set source %d: %w", i, err)
			}
		case Untyped:
			v := values[i]
			if err := src.Set(v); err != nil {
				return fmt.Errorf("failed to set source %d: %w", i, err)
			}
		}
	}

	return nil
}

// AddListener attaches a new change listener to this binding
func (s *sprintf) AddListener(listener DataListener) {
	s.base.AddListener(listener)
}

// RemoveListener detaches a change listener from this binding
func (s *sprintf) RemoveListener(listener DataListener) {
	s.base.RemoveListener(listener)
}

// trigger notifies all listeners that the data has changed
func (s *sprintf) trigger() {
	s.lock.RLock()
	items := s.base.listeners
	s.lock.RUnlock()

	for _, item := range items {
		queueItem(item.DataChanged)
	}
}

