// Set parses the string back using fmt.Sscanf and sets each source binding to the parsed value.
// URI is parsed via storage.ParseURI.
func (s *sprintf) Set(str string) error {
	s.lock.RLock()
	sources := s.sources
	format := s.format
	s.lock.RUnlock()

	if len(sources) == 0 {
		return fmt.Errorf("no source bindings to set")
	}

	// Prepare value pointers for Sscanf based on binding types
	values := make([]interface{}, len(sources))
	for i, source := range sources {
		switch source.(type) {
		case String:
			var v string
			values[i] = &v
		case Int:
			var v int
			values[i] = &v
		case Float:
			var v float64
			values[i] = &v
		case Bool:
			var v bool
			values[i] = &v
		case URI:
			var v string
			values[i] = &v
		case Untyped:
			var v interface{}
			values[i] = &v
		default:
			return fmt.Errorf("unsupported binding type at index %d", i)
		}
	}

	// Use Sscanf to parse the string
	n, err := fmt.Sscanf(str, format, values...)
	if err != nil && n < len(sources) {
		return fmt.Errorf("failed to parse string: %w", err)
	}

	// Set each source binding with the parsed value
	for i, source := range sources {
		var setErr error
		switch src := source.(type) {
		case String:
			setErr = src.Set(*values[i].(*string))
		case Int:
			setErr = src.Set(*values[i].(*int))
		case Float:
			setErr = src.Set(*values[i].(*float64))
		case Bool:
			setErr = src.Set(*values[i].(*bool))
		case URI:
			uri, parseErr := storage.ParseURI(*values[i].(*string))
			if parseErr != nil {
				return fmt.Errorf("failed to parse URI at index %d: %w", i, parseErr)
			}
			setErr = src.Set(uri)
		case Untyped:
			setErr = src.Set(values[i])
		default:
			return fmt.Errorf("unsupported binding type at index %d", i)
		}
		if setErr != nil {
			return fmt.Errorf("failed to set source at index %d: %w", i, setErr)
		}
	}

	return nil
}

